session_start(); require_once __DIR__ . '/../lead-engine/config.php'; if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/');exit;}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function sb144d($m,$ep,$p=null){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>25]);if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));$b=curl_exec($ch);curl_close($ch);$d=json_decode($b,true);return is_array($d)?$d:[];}$msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){$id=$_POST['id']??'';$status=$_POST['status']??'';if($id&&in_array($status,['new','reviewed','callback_needed','callback_done','archived'],true)){sb144d('PATCH','business_call_log?id=eq.'.rawurlencode($id),['status'=>$status,'updated_at'=>date('c')]);$msg='Business call updated.';}}$calls=sb144d('GET','business_call_log?select=*&order=priority_score.desc,call_date.desc&limit=400');$actions=sb144d('GET','business_call_actions?select=*&status=eq.open&order=due_at.asc&limit=100');$briefs=sb144d('GET','business_call_briefings?select=*&order=created_at.desc&limit=5');$brief=$briefs[0]??[];$stats=['total'=>count($calls),'urgent'=>0,'high'=>0,'callback'=>0,'seller'=>0,'buyer'=>0,'vendor'=>0,'agent'=>0];foreach($calls as $c){if(($c['priority']??'')==='urgent')$stats['urgent']++;if(($c['priority']??'')==='high')$stats['high']++;if(!empty($c['needs_callback']))$stats['callback']++;if(($c['call_category']??'')==='seller')$stats['seller']++;if(($c['call_category']??'')==='buyer')$stats['buyer']++;if(($c['call_category']??'')==='vendor')$stats['vendor']++;if(($c['call_category']??'')==='agent')$stats['agent']++;}$cronKey=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'YOUR_KEY';?><!doctype html><