et='_blank' href='/lead-engine/retell/webhook.php?key=<?=h($cronKey)?>&from_number=2032472655&summary=Mark%20test%20business%20call%20seller%20valuation%20callback&transcript=This%20is%20a%20seller%20asking%20Mark%20for%20a%20valuation%20and%20callback%20today'>Demo Forwarded Call</a><a class='btn light' href='/dashboard/voice-intelligence.php'>Voice Intelligence</a><a class='btn light' href='/dashboard/opportunity-pipeline.php'>Pipeline</a></p><section class='grid'><div class='kpi'><div class='n'><?=h($stats['total'])?></div>Total</div><div class='kpi'><div class='n'><?=h($stats['urgent'])?></div>Urgent</div><div class='kpi'><div class='n'><?=h($stats['high'])?></div>High</div><div class='kpi'><div class='n'><?=h($stats['callback'])?></div>Callbacks</div><div class='kpi'><div class='n'><?=h($stats['seller'])?></div>Sellers</div><div class='kpi'><div class='n'><?=h($stats['buyer'])?></div>Buyers</div><div class='kpi'><div class='n'><?=h($stats['vendor'])?></div>Vendors</div><div class='kpi'><div class='n'><?=h($stats['agent'])?></div>Agents</div></section><div class='layout'><section class='panel'><h2>Business Call Log</h2><table><tr><th>Priority</th><th>Caller</th><th>Category</th><th>Summary</th><th>Action</th></tr><?php foreach($calls as $c):?><tr><td class='<?=h($c['priority'])?>'><?=h($c['priority'])?><div class='muted'>Score <?=h($c['priority_score'])?><br><?=h($c['status'])?></div></td><td><strong><?=h($c['caller_display']?:$c['from_number'])?></strong><div class='muted'><?=h($c['from_number'])?><br><?=h($c['call_date'])?></div></td><td><?=h($c['call_category'])?><div class='muted'>Lead: <?=!empty($c['lead_related'])?'yes':'no'?><br>Callback: <?=!empty($c['needs_callback'])?'yes':'no'?></div></td><td><?=h($c['summary'])?><div class='muted'><?=h(substr($c['transcript']??'',0,260))?></div><?php if(!empty($c['recording_url'])):?><a target='_blank' href='<?=h($c['recording_url'])?>'>Recording</a><?php endif;?></td><td><?=h($c['recommended_action'])?><form method='post'><input type='hidden' name='id' value='<?=h($c['id'])?>'><button class='btn' name='status' value='reviewed'>Reviewed</button><button class='btn light' name='status' value='callback_done'>Callback Done</button><button class='btn light' name='status' value='archived'>Archive</button></form></td></tr><?php endforeach;?></table></section><section class='panel'><h2>Concierge Brief</h2><div style='padding:16px'><pre><?=h($brief['briefing_text']??'Build Concierge Brief to create summary.')?></pre></div><h2>Open Actions</h2><table><tr><th>Due</th><th>Action</th></tr><?php foreach($actions as $a):?><tr><td><?=h($a['due_at'])?></td><td><strong><?=h($a['title'])?></strong><div class='muted'><?=h($a['details'])?></div></td></tr><?php endforeach;?></table><h2>Retell Webhook</h2><div style='padding:16px'><pre>https://markpires.com/lead-engine/retell/webhook.php?key=<?=h($cronKey)?></pre></div></section></div></main></body></html>